    _keys_note[x + y*W] = 36 + (8-y)*5 + (x-1)
  end
end
local _keys_scale_member = {{[0]=true,[1]=true,[2]=true,[3]=true,[4]=true,[5]=true,[6]=true,[7]=true,[8]=true,[9]=true,[10]=true,[11]=true},{[0]=true,[2]=true,[4]=true,[5]=true,[7]=true,[9]=true,[11]=true},{[0]=true,[2]=true,[3]=true,[5]=true,[7]=true,[8]=true,[10]=true},{[0]=true,[2]=true,[3]=true,[5]=true,[7]=true,[9]=true,[10]=true},{[0]=true,[1]=true,[3]=true,[5]=true,[7]=true,[8]=true,[10]=true},{[0]=true,[2]=true,[4]=true,[6]=true,[7]=true,[9]=true,[11]=true},{[0]=true,[2]=true,[4]=true,[5]=true,[7]=true,[9]=true,[10]=true},{[0]=true,[1]=true,[3]=true,[5]=true,[6]=true,[8]=true,[10]=true}}
